import json

raw_json = r"""{"result": "<!DOCTYPE html>\n<html lang=\"ko\" xmlns:th=\"http://www.thymeleaf.org\" xmlns:sec=\"http://www.thymeleaf.org/extras/spring-security\">\n<head>\n    <meta th:replace=\"~{fragments/layout :: head(${party.title} + ' | \\ud0c0\\ub178\\uc2dc\\ubbf8')}\">\n    <style>\n      a.back { display:inline-block; text-decoration:none; color:var(--ink-soft); font-size:14px; transition:color .2s; }\n      a.back:hover { color:var(--forest); }\n    </style>\n</head>\n<body>\n<header th:replace=\"~{fragments/layout :: header}\"></header>\n\n<main class=\"wrap\" style=\"max-width:800px; padding:20px;\">\n  <div style=\"margin-bottom:16px;\">\n    <a class=\"back\" th:href=\"@{/party-board}\">\\u2190 [[#{party.back_to_list}]]</a>\n  </div>\n\n  <div class=\"party-box\" style=\"background:var(--card); border:1px solid var(--line); border-radius:16px; overflow:hidden;\">\n    <div style=\"position:relative; height:200px;\">\n      <div th:class=\"${(party.thumbnailUrl != null and !#strings.startsWith(party.thumbnailUrl,'ph')) ? 'ph1' : (party.thumbnailUrl ?: 'ph1')}\"\n           style=\"position:absolute; inset:0;\"\n           th:styleappend=\"${party.thumbnailUrl != null and !#strings.startsWith(party.thumbnailUrl,'ph')} ? 'background-image:url(' + ${party.thumbnailUrl} + '); background-size:cover; background-position:center;' : ''\"></div>\n           \n      <div style=\"position:absolute; top:12px; left:12px; display:flex; gap:6px;\">\n        <span class=\"chip chip-region\" th:text=\"'\\ud83d\\udccd ' + ${party.region}\" style=\"background:var(--sky); color:#1c3a44; font-size:12px; font-weight:700; border-radius:999px; padding:4px 11px; display:inline-block;\">\\uc9c0\\uc5ed</span>\n        \n        <span class=\"chip\" th:text=\"${party.status.name() == 'recruiting'} ? #{party.status.recruiting} : #{party.status.closed}\"\n              th:style=\"${party.status.name() == 'recruiting'} ? 'font-size:12px; font-weight:700; border-radius:999px; padding:4px 11px; display:inline-block; background:var(--forest);color:#fff;' : 'font-size:12px; font-weight:700; border-radius:999px; padding:4px 11px; display:inline-block; background:#8a7a63;color:#fff;'\">\\uc0c1\\ud0dc</span>\n      </div>\n      \n      <div th:if=\"${isOwner}\" style=\"position:absolute; bottom:12px; left:12px;\">\n        <button type=\"button\" class=\"btn\" style=\"background:rgba(255,255,255,.9); font-size:11px; padding:4px 8px;\" onclick=\"document.getElementById('thumbnail-upload').click()\">\\ud83d\\udcf7 [[#{party.thumb.change}]]</button>\n        <input type=\"file\" id=\"thumbnail-upload\" accept=\"image/*\" style=\"display:none;\" onchange=\"changeThumbnail()\">\n      </div>\n\n      <span style=\"position:absolute; bottom:12px; right:12px; background:rgba(58,46,34,.72); color:#fff; font-size:12px; border-radius:999px; padding:4px 10px;\"\n            th:with=\"today=${T(java.time.LocalDate).now()}\"\n            th:text=\"${party.departureDate.isEqual(today) ? 'D-DAY' : (party.departureDate.isAfter(today) ? 'D-' + T(java.time.temporal.ChronoUnit).DAYS.between(today, party.departureDate) : '\\ub9c8\\uac10')}\">D-7</span>\n    </div>\n    \n    <div style=\"padding:20px;\">\n      <div style=\"display:flex; justify-content:space-between; align-items:flex-start;\">\n        <h1 style=\"font-size:21px; margin:0;\" id=\"party-title\" th:text=\"${party.title}\">\\uc81c\\ubaa9</h1>\n        <button type=\"button\" class=\"btn translate-btn\" style=\"font-size:10px; padding:4px 8px; border:1px solid var(--line); border-radius:4px; cursor:pointer; background:#fff;\" onclick=\"translatePost()\">\\ubc88\\uc5ed \\ud83c\\udf0d</button>\n      </div>\n\n      <p style=\"color:var(--ink-soft); font-size:13px; margin-top:6px; line-height:1.5;\" id=\"party-desc\" th:text=\"${party.description}\">\\ub0b4\\uc6a9</p>\n\n      <div style=\"margin-top:16px; padding:16px; background:#f9f9f9; border-radius:8px; display:flex; flex-direction:column; gap:8px; font-size:13px;\">\n        <div style=\"display:flex; justify-content:space-between;\">\n          <span>[[#{party.meta.schedule}]] <b th:text=\"${party.departureDate}\">-</b></span>\n          <span th:if=\"${party.budgetKrw != null}\">[[#{party.meta.budget}]] <b th:text=\"${party.budgetKrw} + #{party.meta.budget_approx}\">-</b></span>\n        </div>\n        <div style=\"display:flex; justify-content:space-between;\">\n          <span>[[#{party.meta.gender}]] <b th:text=\"${party.genderRestriction.name() == 'all'} ? #{party.gender.all} : (${party.genderRestriction.name() == 'male_only'} ? #{party.gender.male_only} : #{party.gender.female_only})\">-</b></span>\n          <span>[[#{party.meta.capacity}]] <b th:text=\"${party.capacity} + '\\uba85'\">-</b></span>\n        </div>\n        <div style=\"display:flex; justify-content:space-between;\">\n          <span th:if=\"${party.ageMin != null or party.ageMax != null}\">\n            [[#{party.meta.age}]] <b th:text=\"(${party.ageMin} ?: '') + '~' + (${party.ageMax} ?: '') + #{party.meta.age_range}\">-</b>\n          </span>\n          <span th:if=\"${party.nationalityRestriction.name() != 'all'}\">\n            [[#{party.nationality}]] <b th:text=\"${party.nationalityRestriction.name() == 'kr_only'} ? #{party.nationality.kr_only} : #{party.nationality.jp_only}\">-</b>\n          </span>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div style=\"margin-top:24px; background:var(--card); border:1px solid var(--line); border-radius:12px; padding:20px;\">\n    <h2 style=\"font-size:15px; margin-top:0;\">[[#{party.apply}]]</h2>\n    \n    <div th:if=\"${!eligible and ineligibleReasonKey != null}\" style=\"padding:12px; background:#ffeeee; border:1px solid #ffcccc; color:#cc0000; border-radius:8px; font-size:13px;\">\n      \\ud83d\\udeab <span th:text=\"#{${ineligibleReasonKey}}\">\\uc870\\uac74\\uc5d0 \\ub9de\\uc9c0 \\uc54a\\uc2b5\\ub2c8\\ub2e4.</span>\n    </div>\n\n    <div th:if=\"${eligible and !isOwner}\">\n      <div style=\"margin-bottom:12px;\">\n        <textarea id=\"apply-message\" maxlength=\"300\" th:placeholder=\"#{party.apply.placeholder}\"\n                  style=\"width:100%; min-height:80px; padding:10px; border:1px solid var(--line); border-radius:8px; font-family:inherit;\"></textarea>\n      </div>\n      <div style=\"text-align:right;\">\n        <button type=\"button\" class=\"btn btn-primary\" id=\"btn-apply\"\n                th:attr=\"data-party-id=${party.id}\" th:text=\"#{party.apply}\">\\uc2e0\\uccad\\ud558\\uae30</button>\n      </div>\n    </div>\n  </div>\n  \n</main>\n<script th:src=\"@{/js/csrf.js}\"></script>\n<script th:inline=\"javascript\">\n  const MSG_ERROR = /*[[#{error.general}]]*/ '\\uc624\\ub958\\uac00 \\ubc1c\\uc0dd\\ud588\\uc2b5\\ub2c8\\ub2e4.';\n\n  const btnApply = document.getElementById('btn-apply');\n  if (btnApply) {\n      btnApply.addEventListener('click', async () => {\n          const msg = document.getElementById('apply-message').value.trim();\n          const partyId = btnApply.dataset.partyId;\n          const body = { message: msg };\n          \n          let csrfToken = document.querySelector('meta[name=\"_csrf\"]')?.content || '';\n          let csrfHeader = document.querySelector('meta[name=\"_csrf_header\"]')?.content || 'X-CSRF-TOKEN';\n          \n          try {\n              const res = await fetch(`/api/parties/${partyId}/apply`, {\n                  method: 'POST',\n                  headers: {\n                      'Content-Type': 'application/json',\n                      ...(csrfToken ? {[csrfHeader]: csrfToken} : {})\n                  },\n                  body: JSON.stringify(body)\n              });\n              const data = await res.json();\n              if (data.success) {\n                  window.location.href = '/my-parties';\n              } else {\n                  alert(data.message || MSG_ERROR);\n              }\n          } catch (e) {\n              alert(MSG_ERROR);\n          }\n      });\n  }\n\n  async function translatePost() {\n      const titleEl = document.getElementById('party-title');\n      const descEl = document.getElementById('party-desc');\n      let docLang = document.documentElement.lang;\n      const targetLang = docLang === 'ja' ? 'ja' : 'ko';\n      try {\n          const r1 = await window.api.post('/api/chat/translate', {text: titleEl.textContent, targetLang: targetLang});\n          if(r1.success) titleEl.textContent = r1.data;\n          const r2 = await window.api.post('/api/chat/translate', {text: descEl.textContent, targetLang: targetLang});\n          if(r2.success) descEl.textContent = r2.data;\n      } catch(e) {}\n  }\n  \n  if (document.documentElement.lang === 'ja') {\n      window.addEventListener('load', () => translatePost());\n  }\n\n  async function changeThumbnail() {\n      const fileInput = document.getElementById('thumbnail-upload');\n      const file = fileInput.files[0];\n      if (!file) return;\n      const partyId = window.location.pathname.split('/').pop();\n      const formData = new FormData();\n      formData.append('file', file);\n      \n      let csrfToken = document.querySelector('meta[name=\"_csrf\"]')?.content || '';\n      let csrfHeader = document.querySelector('meta[name=\"_csrf_header\"]')?.content || 'X-CSRF-TOKEN';\n      \n      try {\n          const res = await fetch(`/api/parties/${partyId}/thumbnail`, {\n              method: 'POST',\n              headers: csrfToken ? {[csrfHeader]: csrfToken} : {},\n              body: formData\n          });\n          const data = await res.json();\n          if (data.success) {\n              window.location.reload();\n          } else {\n              alert(data.message || MSG_ERROR);\n          }\n      } catch (e) {\n          alert('\\uc624\\ub958\\uac00 \\ubc1c\\uc0dd\\ud588\\uc2b5\\ub2c8\\ub2e4.');\n      }\n  }\n</script>\n</body>\n</html>"}"""

data = json.loads(raw_json)
html = data["result"]
html = html.replace('/api/party/${partyId}/apply', '/api/parties/${partyId}/apply')

with open('src/main/resources/templates/party/detail.html', 'w', encoding='utf-8') as f:
    f.write(html)
